import{_ as a,o as i,c as s,a7 as t}from"./chunks/framework.CQwaBCkA.js";const k=JSON.parse('{"title":"兼容性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":1792768820000}'),l={name:"guide/compatibility.md"};function r(n,e,d,h,p,o){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h1><h2 id="安装渠道与接口版本" tabindex="-1">安装渠道与接口版本 <a class="header-anchor" href="#安装渠道与接口版本" aria-label="Permalink to &quot;安装渠道与接口版本&quot;">​</a></h2><p>支持 Vue <code>3.0+</code>，正式版使用默认的 <code>latest</code> 渠道：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-fullscreen</span></span></code></pre></div><p>本文档的接口参考版本为 <code>5.0.0</code>。Vue 2 用户请使用 <code>vue-fullscreen@legacy</code>，见 <a href="/vue2/guide/compatibility">Vue 2 兼容性说明</a>。</p><h2 id="fullscreen-api-浏览器支持" tabindex="-1">Fullscreen API 浏览器支持 <a class="header-anchor" href="#fullscreen-api-浏览器支持" aria-label="Permalink to &quot;Fullscreen API 浏览器支持&quot;">​</a></h2><p>原生全屏由浏览器提供。完整版本列表见 <a href="https://caniuse.com/fullscreen" target="_blank" rel="noreferrer">Can I use：Fullscreen API</a>，设备限制见 <a href="https://developer.mozilla.org/en-US/docs/Web/API/Element/requestFullscreen#browser_compatibility" target="_blank" rel="noreferrer">MDN 的 requestFullscreen 兼容性表</a>。以下为常见环境概览。</p><table tabindex="0"><thead><tr><th>浏览器 / 设备</th><th>原生全屏支持</th></tr></thead><tbody><tr><td>桌面 Chrome / Edge</td><td>Chrome 71+、Edge 79+ 支持标准 API</td></tr><tr><td>桌面 Firefox</td><td>64+ 支持标准 API</td></tr><tr><td>macOS Safari</td><td>16.4+ 支持标准 API；更早版本有带前缀的部分支持</td></tr><tr><td>iPad Safari</td><td>iPadOS 16.4+ 支持标准 API，但有设备限制；较早版本有带前缀的部分支持</td></tr><tr><td>iPhone Safari</td><td>不支持任意元素的 Fullscreen API；使用网页全屏</td></tr><tr><td>Android Chrome / Firefox</td><td>当前版本支持，具体版本见支持表</td></tr><tr><td>Internet Explorer</td><td>IE 11 仅部分支持原生 API；本组件包不支持 IE</td></tr></tbody></table><p>表中的版本号描述浏览器 API，不是本组件包的最低浏览器版本或实机测试承诺。本包构建面向 ES2018。底层 <code>screenfull</code> 处理部分浏览器前缀差异，但不能补齐浏览器缺失的全屏能力。</p><h3 id="safari-与移动设备" tabindex="-1">Safari 与移动设备 <a class="header-anchor" href="#safari-与移动设备" aria-label="Permalink to &quot;Safari 与移动设备&quot;">​</a></h3><p>iPad 原生全屏会显示浏览器提供的退出控件，下滑等系统手势也可能退出。iPhone 的视频播放器全屏是独立能力，不代表图表、普通 <code>div</code> 或整个页面可以原生全屏。Safari 16.4 的改动可参阅 <a href="https://webkit.org/blog/13966/webkit-features-in-safari-16-4/" target="_blank" rel="noreferrer">WebKit 发布说明</a>。</p><h3 id="internet-explorer" tabindex="-1">Internet Explorer <a class="header-anchor" href="#internet-explorer" aria-label="Permalink to &quot;Internet Explorer&quot;">​</a></h3><p>当前版本基于 Vue 3，不支持 IE；<code>Promise</code> polyfill 不能补齐 Vue 3 所需的 Proxy 能力。需要 IE 11 时，请使用独立的 <a href="/vue2/guide/compatibility">Vue 2 版本及兼容性说明</a>。</p><h2 id="用户操作与-iframe-权限" tabindex="-1">用户操作与 iframe 权限 <a class="header-anchor" href="#用户操作与-iframe-权限" aria-label="Permalink to &quot;用户操作与 iframe 权限&quot;">​</a></h2><p>原生全屏<strong>只能由</strong>点击、触摸或按键等用户操作触发。不要先等待网络请求再调用全屏 API，以免用户激活状态过期。</p><p>嵌入页面需要允许全屏，例如：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/example/&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fullscreen&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allowfullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>父页面的 <code>Permissions-Policy</code> 仍可能限制全屏；仅添加 iframe 属性不能覆盖更严格的响应头策略。</p><h2 id="能力检测与网页全屏降级" tabindex="-1">能力检测与网页全屏降级 <a class="header-anchor" href="#能力检测与网页全屏降级" aria-label="Permalink to &quot;能力检测与网页全屏降级&quot;">​</a></h2><p>在浏览器中读取 <code>useFullscreen()</code> 返回的 <code>isSupported</code>，可判断当前文档是否允许使用原生全屏。它不表示是否已经进入全屏，也不保证下一次请求一定成功。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useFullscreen } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue-fullscreen&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 在组件挂载后或用户点击时读取</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">isSupported</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useFullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nativeAvailable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> isSupported.value</span></span></code></pre></div><ul><li>原生全屏不可用时，组件、指令和 API 自动使用网页全屏。</li><li>显式设置 <code>pageOnly: true</code>（组件属性为 <code>page-only</code>）时，始终使用网页全屏。</li><li>原生能力可用但请求被拒绝时，会报告错误并恢复 DOM，不会静默降级。API 调用应捕获 Promise 拒绝，组件使用 <code>error</code> 事件，指令使用 <code>fullscreen-error</code> 事件。</li></ul><p>网页全屏保留浏览器工具栏，只覆盖当前文档的视口。在 iframe 内，它只能覆盖 iframe 区域；<code>teleport</code> 也只会移动到该文档的 <code>body</code>，不能突破 iframe 边界。</p>`,23)])])}const u=a(l,[["render",r]]);export{k as __pageData,u as default};
